#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<double> x(N), y(N);
    for(int i=0;i<N;i++) cin >> x[i] >> y[i];

    // Sieve primes up to N
    vector<bool> is_prime(N, false);
    if(N > 2){
        vector<bool> sieve(N, true);
        sieve[0] = sieve[1] = false;
        for(int i=2; i*i < N; i++)
            if(sieve[i])
                for(int j=i*i; j<N; j+=i)
                    sieve[j] = false;
        is_prime = sieve;
    }

    auto dist = [&](int a, int b) -> double {
        double dx = x[a]-x[b], dy = y[a]-y[b];
        return sqrt(dx*dx + dy*dy);
    };

    // Compute tour cost
    auto tourCost = [&](const vector<int>& tour) -> double {
        double cost = 0;
        for(int t=1; t<=N; t++){
            double d = dist(tour[t-1], tour[t]);
            if(t % 10 == 0 && !is_prime[tour[t-1]])
                d *= 1.1;
            cost += d;
        }
        return cost;
    };

    // Build initial tour: nearest neighbor
    vector<int> tour(N+1);
    tour[0] = 0; tour[N] = 0;
    vector<bool> visited(N, false);
    visited[0] = true;

    for(int i=1; i<N; i++){
        int last = tour[i-1];
        int best = -1;
        double bestd = 1e18;
        // For speed with large N, sample random candidates + nearby by index
        if(N <= 5000){
            for(int j=0;j<N;j++){
                if(!visited[j]){
                    double d = dist(last,j);
                    if(d < bestd){ bestd=d; best=j; }
                }
            }
        } else {
            // Since sorted by x, check nearby indices + random
            for(int delta=-500; delta<=500; delta++){
                int j = last + delta;
                if(j>=0 && j<N && !visited[j]){
                    double d = dist(last,j);
                    if(d<bestd){bestd=d;best=j;}
                }
            }
            // Also random sampling
            mt19937 rng(42+i);
            for(int k=0;k<200;k++){
                int j = rng()%N;
                if(!visited[j]){
                    double d=dist(last,j);
                    if(d<bestd){bestd=d;best=j;}
                }
            }
            if(best==-1){
                for(int j=0;j<N;j++) if(!visited[j]){best=j;break;}
            }
        }
        tour[i] = best;
        visited[best] = true;
    }

    double bestCost = tourCost(tour);

    // 2-opt local search (time-limited)
    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    bool improved = true;
    while(improved && elapsed() < 1.8){
        improved = false;
        for(int i=1; i<N-1 && elapsed()<1.8; i++){
            for(int j=i+1; j<N && j-i<300 && elapsed()<1.8; j++){
                // Reverse segment [i..j]
                reverse(tour.begin()+i, tour.begin()+j+1);
                double nc = tourCost(tour);
                if(nc < bestCost - 1e-9){
                    bestCost = nc;
                    improved = true;
                } else {
                    reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
